import "./styles/index.css"

import type { Content, Editor as TiptapEditor } from "@tiptap/react"
import { EditorContent, EditorContext } from "@tiptap/react"

import { cn } from "@/lib/utils"
import { Separator } from "@/registry/preskok/ui/separator"

import { LinkBubbleMenu } from "./components/bubble-menu/link-bubble-menu"
import { MeasuredContainer } from "./components/measured-container"
import { SectionFive } from "./components/section/five"
import { SectionFour } from "./components/section/four"
import { SectionOne } from "./components/section/one"
import { SectionThree } from "./components/section/three"
import { SectionTwo } from "./components/section/two"
import type { UseMinimalTiptapEditorProps } from "./hooks/use-editor"
import { useEditor } from "./hooks/use-editor"
import { useTiptapEditor } from "./hooks/use-tiptap-editor"

const DEFAULT_ACTIVE_LEVELS: Array<1 | 2 | 3 | 4 | 5 | 6> = [1, 2, 3, 4, 5, 6]
const DEFAULT_TEXT_STYLE_ACTIONS: Array<
  "bold" | "italic" | "underline" | "strikethrough" | "clearFormatting"
> = ["bold", "italic", "underline", "strikethrough", "clearFormatting"]
const DEFAULT_LIST_ACTIONS: Array<"orderedList" | "bulletList"> = [
  "orderedList",
  "bulletList",
]
const DEFAULT_INSERT_ACTIONS: Array<"blockquote" | "horizontalRule"> = [
  "blockquote",
  "horizontalRule",
]

export interface MinimalTiptapProps extends Omit<
  UseMinimalTiptapEditorProps,
  "onUpdate"
> {
  value?: Content
  onChange?: (value: Content) => void
  className?: string
  editorContentClassName?: string
}

const Toolbar = ({ editor }: { editor: TiptapEditor }) => (
  <div className="border-border flex shrink-0 overflow-x-auto border-b px-2 py-1.5">
    <div className="flex w-max items-center gap-px">
      <SectionOne editor={editor} activeLevels={DEFAULT_ACTIVE_LEVELS} />

      <Separator
        orientation="vertical"
        className="mx-1 data-[orientation=vertical]:h-3/4!"
      />

      <SectionTwo
        editor={editor}
        activeActions={DEFAULT_TEXT_STYLE_ACTIONS}
        mainActionCount={3}
      />

      <Separator
        orientation="vertical"
        className="mx-1 data-[orientation=vertical]:h-3/4!"
      />

      <SectionThree editor={editor} />

      <Separator
        orientation="vertical"
        className="mx-1 data-[orientation=vertical]:h-3/4!"
      />

      <SectionFour
        editor={editor}
        activeActions={DEFAULT_LIST_ACTIONS}
        mainActionCount={0}
      />

      <Separator
        orientation="vertical"
        className="mx-1 data-[orientation=vertical]:h-3/4!"
      />

      <SectionFive
        editor={editor}
        activeActions={DEFAULT_INSERT_ACTIONS}
        mainActionCount={0}
      />
    </div>
  </div>
)

export const Editor = ({
  value,
  onChange,
  className,
  editorContentClassName,
  ...props
}: MinimalTiptapProps) => {
  const editor = useEditor({
    value,
    onUpdate: onChange,
    ...props,
  })

  if (!editor) {
    return null
  }

  return (
    <EditorContext value={{ editor }}>
      <MainEditor
        editor={editor}
        className={className}
        editorContentClassName={editorContentClassName}
      />
    </EditorContext>
  )
}

export const MainEditor = ({
  editor: providedEditor,
  className,
  editorContentClassName,
}: MinimalTiptapProps & { editor: TiptapEditor }) => {
  const { editor } = useTiptapEditor(providedEditor)

  if (!editor) {
    return null
  }

  return (
    <MeasuredContainer
      as="div"
      name="editor"
      className={cn(
        "border-border min-data-[orientation=vertical]:h-72 flex h-auto w-full flex-col rounded-md border",
        className
      )}
    >
      <Toolbar editor={editor} />
      <EditorContent
        editor={editor}
        className={cn(
          "minimal-tiptap-editor h-full px-5 py-4 focus:outline-hidden",
          editorContentClassName
        )}
      />
      <LinkBubbleMenu editor={editor} />
    </MeasuredContainer>
  )
}

import type { Editor } from "@tiptap/react"

import type { MinimalTiptapProps } from "./editor"

type ShortcutKeyResult = {
  symbol: string
  readable: string
}

export const isClient = (): boolean => typeof window !== "undefined"

export const isMacOS = (): boolean =>
  isClient() && window.navigator.userAgent.includes("Macintosh")

const shortcutKeyMap = {
  mod: isMacOS()
    ? { symbol: "⌘", readable: "Command" }
    : { symbol: "Ctrl", readable: "Control" },
  alt: isMacOS()
    ? { symbol: "⌥", readable: "Option" }
    : { symbol: "Alt", readable: "Alt" },
  shift: { symbol: "⇧", readable: "Shift" },
} as const satisfies Record<string, ShortcutKeyResult>

type ShortcutKey =
  | Uppercase<keyof typeof shortcutKeyMap>
  | Lowercase<keyof typeof shortcutKeyMap>

export const getShortcutKey = (key: ShortcutKey): ShortcutKeyResult => {
  const lowerKey = key.toLowerCase() as Lowercase<keyof typeof shortcutKeyMap>
  const result = shortcutKeyMap[lowerKey]
  return result || { symbol: key, readable: key }
}

export const getShortcutKeys = (
  keys: Array<ShortcutKey>
): Array<ShortcutKeyResult> => keys.map(getShortcutKey)

export const getOutput = (
  editor: Editor,
  format: MinimalTiptapProps["output"]
): object | string => {
  switch (format) {
    case "json":
      return editor.getJSON()
    case "html":
      return editor.isEmpty ? "" : editor.getHTML()
    default:
      return editor.getText()
  }
}

import { HorizontalRule as TiptapHorizontalRule } from "@tiptap/extension-horizontal-rule"

export const HorizontalRule = TiptapHorizontalRule.extend({
  addKeyboardShortcuts() {
    return {
      "Mod-Alt--": () =>
        this.editor.commands.insertContent({
          type: this.name,
        }),
    }
  },
})

import { Extension } from "@tiptap/react"

export const ResetMarksOnEnter = Extension.create({
  name: "resetMarksOnEnter",

  addKeyboardShortcuts() {
    return {
      Enter: ({ editor }) => {
        if (
          editor.isActive("bold") ||
          editor.isActive("italic") ||
          editor.isActive("strike") ||
          editor.isActive("underline") ||
          editor.isActive("code")
        ) {
          editor.commands.splitBlock({ keepMarks: false })

          return true
        }

        return false
      },
    }
  },
})

import { Extension } from "@tiptap/react"

export const UnsetAllMarks = Extension.create({
  addKeyboardShortcuts() {
    return {
      "Mod-\\": () => this.editor.commands.unsetAllMarks(),
    }
  },
})

import { Color as TiptapColor } from "@tiptap/extension-color"
import { Plugin } from "@tiptap/pm/state"

export const Color = TiptapColor.extend({
  addProseMirrorPlugins() {
    return [
      ...(this.parent?.() || []),
      new Plugin({
        props: {
          handleKeyDown: (_, event) => {
            if (event.key === "Enter") {
              this.editor.commands.unsetColor()
            }
            return false
          },
        },
      }),
    ]
  },
})

